/*!
 * Themeasy — Elementor Library Panel
 *
 * Drives the in-editor Themeasy Library: adds a launcher to Elementor's "add new
 * section" buttons (floating fallback), opens a modal that browses the backstage
 * catalog through the same-origin proxy (Library_Ajax) merged with the theme's
 * local template JSON (Library_Local), and renders a filterable, paginated card
 * grid. The tag bar and the card chips show the library's most-used tags, never
 * its whole tag list. Top-level parent categories render as group tabs (Pages / Blocks —
 * data-driven from the category hierarchy, hidden on a flat catalog) whose child
 * categories fill the sidebar; a tab filters by the parent slug, which the
 * backstage expands to children server-side. One-click insertion loads the
 * template envelope through the proxy (local templates are read from disk) and
 * appends its elements to the open document. A locked `pro` card shows a lock
 * and an upgrade link; theme-bundled cards carry a "Theme" badge and always
 * insert.
 *
 * Requests retry transient failures once and responses are sequence-guarded, so
 * an out-of-order reply can never clobber newer results. Vanilla, namespaced,
 * idempotent, and degrades gracefully — the editor is fully usable if this
 * script no-ops. All remote strings are written via textContent and remote URLs
 * are scheme-checked before use.
 *
 * @author Themeasy
 * @link https://themeasy.co
 * @since 1.0.0
 */

(function (window, document) {
  'use strict';

  window.Themeasy = window.Themeasy || {};

  // Bail quietly if the bootstrap payload is missing — nothing to wire.
  const cfg = window.themeasyLibrary;
  if (!cfg || !cfg.ajaxUrl || !cfg.nonce) {
    return;
  }

  const i18n = cfg.i18n || {};

  // ------------------------------------------------------------------------
  // State
  // ------------------------------------------------------------------------

  // Group tab preferred as the default selection when present: users reach for
  // whole pages first, so the full-page group leads and opens the modal.
  const DEFAULT_GROUP = 'pages';

  // Pills in the tag bar and chips on a card. The backstage holds 1,100+ tags,
  // about 15 per template, so both show the library's most-used ones (backlog
  // #357): listing every tag pushed the grid out of the modal.
  const TAG_BAR_SIZE = 12;
  const CARD_TAGS_SIZE = 3;

  const state = {
    built: false,
    // Meta resources latch to 'done' only on success — a failed fetch returns
    // to 'idle' so the next open()/Retry re-attempts instead of freezing the
    // sidebar on "All categories" forever.
    metaCategories: 'idle',
    metaTags: 'idle',
    // Monotonic listing-request id: only the newest request may render, so a
    // slow, out-of-order response can never clobber fresher results.
    requestSeq: 0,
    categories: [],
    // Top-level parent categories (tabs), derived from `categories`; empty on
    // a flat catalog, which keeps the original tab-less layout.
    groups: [],
    activeGroup: '',
    tags: [],
    templates: [],
    total: 0,
    page: 1,
    pages: 1,
    filters: { category: '', tag: '', search: '' }
  };

  // DOM references, populated by buildModal().
  const dom = {};

  // Native-launcher state: whether at least one add-section button has landed,
  // the live observer on the preview iframe (re-targeted on each reload),
  // whether the floating fallback may be scheduled yet (only once the preview
  // has confirmed loaded), and its pending grace timer.
  let nativeInjected = false;
  let previewObserver = null;
  let fallbackArmed = false;
  let fallbackTimer = null;

  // ------------------------------------------------------------------------
  // Helpers
  // ------------------------------------------------------------------------

  /**
   * Create an element with attributes and children.
   *
   * @param {string} tag
   * @param {Object} [props] - class/text/attrs/on handlers.
   * @param {Array}  [children]
   * @returns {HTMLElement}
   */
  function el(tag, props, children) {
    const node = document.createElement(tag);
    props = props || {};

    Object.keys(props).forEach(function (key) {
      const value = props[key];
      if (key === 'class') {
        node.className = value;
      } else if (key === 'text') {
        node.textContent = value;
      } else if (key.indexOf('on') === 0 && typeof value === 'function') {
        node.addEventListener(key.slice(2).toLowerCase(), value);
      } else if (value !== null && value !== false && value !== undefined) {
        node.setAttribute(key, value);
      }
    });

    (children || []).forEach(function (child) {
      if (child === null || child === undefined || child === false) {
        return;
      }
      node.appendChild(typeof child === 'string' ? document.createTextNode(child) : child);
    });

    return node;
  }

  /**
   * Whether a value is a safe http(s) URL we can put in src/href.
   *
   * @param {*} value
   * @returns {boolean}
   */
  function isHttpUrl(value) {
    return typeof value === 'string' && /^https?:\/\//i.test(value);
  }

  /**
   * Debounce a function.
   *
   * @param {Function} fn
   * @param {number} wait
   * @returns {Function}
   */
  function debounce(fn, wait) {
    let timer = null;
    return function () {
      const args = arguments;
      const ctx = this;
      window.clearTimeout(timer);
      timer = window.setTimeout(function () {
        fn.apply(ctx, args);
      }, wait);
    };
  }

  /**
   * Format a template string with %1$s / %2$s positional placeholders.
   *
   * @param {string} template
   * @param {Array} values
   * @returns {string}
   */
  function format(template, values) {
    return String(template || '').replace(/%(\d+)\$s/g, function (match, index) {
      const pos = parseInt(index, 10) - 1;
      return values[pos] !== undefined ? values[pos] : match;
    });
  }

  /**
   * A promise that resolves after the given delay.
   *
   * @param {number} ms
   * @returns {Promise<void>}
   */
  function delay(ms) {
    return new Promise(function (resolve) {
      window.setTimeout(resolve, ms);
    });
  }

  // Proxy error codes worth one automatic retry: transient upstream conditions
  // ('unavailable' = browse 502, 'content' = insert payload 502). Application
  // verdicts (nonce, cap, forbidden, resource, id) must never be re-fired.
  const RETRYABLE_CODES = { unavailable: true, content: true };

  /**
   * POST to the same-origin proxy, retrying a transient failure once.
   *
   * Network-level failures (fetch rejection, non-JSON body) and retryable proxy
   * codes get a single delayed re-attempt before surfacing an error — a lone
   * hiccup should never reach the user as a Retry prompt.
   *
   * @param {Object} fields - Form fields (action + params); nonce is appended.
   * @returns {Promise<Object>}
   */
  function postForm(fields) {
    const body = new FormData();
    Object.keys(fields).forEach(function (key) {
      body.append(key, fields[key]);
    });
    body.append('nonce', cfg.nonce);

    function attempt(retriesLeft) {
      return window.fetch(cfg.ajaxUrl, {
        method: 'POST',
        credentials: 'same-origin',
        body: body
      }).then(function (response) {
        return response.json();
      }).then(function (json) {
        if (!json || !json.success) {
          const data = (json && json.data) || {};
          if (retriesLeft > 0 && RETRYABLE_CODES[data.code] === true) {
            return delay(500).then(function () {
              return attempt(retriesLeft - 1);
            });
          }
          throw new Error(data.message || i18n.error || 'Error');
        }
        return json.data;
      }, function () {
        // fetch/JSON failure — network-level, always worth the one retry.
        if (retriesLeft > 0) {
          return delay(500).then(function () {
            return attempt(retriesLeft - 1);
          });
        }
        throw new Error(i18n.error || 'Error');
      });
    }

    return attempt(1);
  }

  /**
   * POST a browse request to the same-origin proxy.
   *
   * @param {string} resource
   * @param {Object} [extra]
   * @returns {Promise<Object>}
   */
  function browse(resource, extra) {
    const fields = { action: 'themeasy_library_browse', resource: resource };

    if (extra) {
      Object.keys(extra).forEach(function (key) {
        fields[key] = extra[key];
      });
    }

    return postForm(fields);
  }

  // ------------------------------------------------------------------------
  // Launcher
  // ------------------------------------------------------------------------

  /**
   * Mount the floating launcher — the fallback entry point, pinned to the
   * editor chrome and deliberately decoupled from Elementor's internal panel
   * DOM (which shifts between versions and Editor V2). Raised only when the
   * native add-section button cannot land: a loaded preview that settled with
   * no add-section area, or an editor whose API never came up.
   *
   * @returns {void}
   */
  function mountLauncher() {
    // The floating launcher is only a stand-in for the native add-section
    // buttons — never raise it if a native one already landed (mutual exclusion).
    if (nativeInjected || document.querySelector('.themeasy-library-launch')) {
      return;
    }
    document.body.appendChild(buildLauncher());
  }

  /**
   * Remove the floating fallback launcher if it is currently mounted.
   *
   * Retires the fallback the moment a native add-section button appears, so a
   * slow preview that raised the floating button first can never leave both
   * entry points on screen at once.
   *
   * @returns {void}
   */
  function removeFloatingLauncher() {
    const floating = document.querySelector('.themeasy-library-launch');
    if (floating) {
      floating.remove();
    }
  }

  /**
   * Build the floating launcher button.
   *
   * @returns {HTMLElement}
   */
  function buildLauncher() {
    const button = el('button', {
      type: 'button',
      class: 'themeasy-library-launch themeasy-library-launch--floating',
      'aria-label': i18n.launch || 'Themeasy Library'
    }, [
      el('span', { class: 'themeasy-library-launch__icon' }),
      el('span', { text: i18n.launch || 'Themeasy Library' })
    ]);

    button.addEventListener('click', open);
    return button;
  }

  // ------------------------------------------------------------------------
  // Native launcher — Elementor "add new section" area (preview iframe)
  // ------------------------------------------------------------------------

  // The Themeasy mark as an inline mask source. Duplicated from the editor CSS
  // because the add-section button lives inside the preview iframe, which does
  // not load the editor-panel stylesheet, so it must carry its own icon styling.
  const THEMEASY_MARK = 'data:image/svg+xml;base64,';

  // How long the editor-API poll runs before treating the editor as broken or
  // incompatible (last-resort floating launcher). elementor.$preview exists
  // early in any healthy boot — well before the preview itself finishes — so
  // this ceiling never trips on a merely slow machine.
  const API_POLL_CEILING = 30000;

  // Quiet period the loaded preview must hold — no childList mutations and no
  // native button — before the floating fallback is raised. Every mutation
  // pushes the deadline back, so the fallback can only fire on a document that
  // finished rendering and truly offers no add-section area.
  const FALLBACK_GRACE = 4000;

  /**
   * (Re)schedule the floating-fallback grace timer. Inert until the document
   * render is confirmed ('document:loaded' sets fallbackArmed — the views,
   * including the add-section areas, are attached by then); after that, each
   * preview mutation re-arms the timer, so the fallback only fires once the
   * rendered DOM has settled without a native button. Anchoring to editor
   * state instead of a wall clock is what keeps the floating button from ever
   * flashing during a normal (even slow or heavy) boot.
   *
   * @returns {void}
   */
  function scheduleFloatingFallback() {
    if (!fallbackArmed || nativeInjected) {
      return;
    }

    window.clearTimeout(fallbackTimer);
    fallbackTimer = window.setTimeout(function () {
      if (!nativeInjected) {
        mountLauncher();
      }
    }, FALLBACK_GRACE);
  }

  /**
   * Resolve the preview iframe's document, when reachable.
   *
   * @returns {Document|null}
   */
  function previewDocument() {
    const iframe = window.elementor.$preview && window.elementor.$preview[0];
    return (iframe && (iframe.contentDocument || (iframe.contentWindow && iframe.contentWindow.document))) || null;
  }

  /**
   * Place a Themeasy launcher next to Elementor's own Add / Template / AI buttons
   * in every "add new section" area — the native, contextual entry point. Polls
   * for the Elementor editor API; if it never appears at all (crashed or
   * incompatible editor), raises the floating launcher as a last resort so an
   * entry point still exists.
   *
   * @returns {void}
   */
  function mountAddSectionLaunchers() {
    let waited = 0;

    const poll = window.setInterval(function () {
      waited += 200;

      if (typeof window.elementor !== 'undefined' && window.elementor.on && window.elementor.$preview) {
        window.clearInterval(poll);
        setupAddSection();
      } else if (waited >= API_POLL_CEILING) {
        window.clearInterval(poll);
        if (!nativeInjected) {
          mountLauncher();
        }
      }
    }, 200);
  }

  /**
   * Wire the preview document: inject now if it is ready, and re-inject whenever
   * the preview reloads or its DOM changes (Elementor re-renders the add-section
   * areas constantly). The floating fallback clock starts only at
   * 'document:loaded' (fired after the views are attached to the preview) and
   * every mutation pushes it back — so the fallback can only appear when a
   * rendered, settled document truly offers no add-section area, never over
   * the loading screen or mid-render on a heavy page.
   *
   * @returns {void}
   */
  function setupAddSection() {
    const inject = function () {
      const doc = previewDocument();
      if (!doc || !doc.body) {
        return;
      }

      injectAddButtons(doc);

      if (previewObserver) {
        previewObserver.disconnect();
      }
      previewObserver = new MutationObserver(debounce(function () {
        injectAddButtons(doc);
        // Preview still rendering — push the fallback deadline back.
        scheduleFloatingFallback();
      }, 150));
      previewObserver.observe(doc.body, { childList: true, subtree: true });
    };

    // Re-wire on every preview (re)load; the injection itself rides inject()
    // + the MutationObserver.
    window.elementor.on('preview:loaded', inject);

    // 'document:loaded' is the ONLY trigger that may start the fallback
    // clock: Elementor fires it after attachDocumentToPreview() resolves, so
    // the views — including the add-section areas — are already rendered.
    // Every earlier signal is a false positive that flashes the floating
    // button during a normal boot and retires it moments later: the iframe
    // reports readyState 'complete' and 'preview:loaded' fires long before
    // the views render, and DOM-settle heuristics misread the pre-render
    // quiet of a still-compiling editor (the loading overlay belongs to the
    // parent document). If the event never fires, inject() + the observer
    // still mount the native button, and no fallback is the safe default.
    window.elementor.on('document:loaded', function () {
      inject();
      fallbackArmed = true;
      scheduleFloatingFallback();
    });
    inject();
  }

  /**
   * Inject the Themeasy button into any add-section area still missing it.
   *
   * @param {Document} doc - The preview iframe document.
   * @returns {void}
   */
  function injectAddButtons(doc) {
    const areas = doc.querySelectorAll('.elementor-add-new-section');

    Array.prototype.forEach.call(areas, function (area) {
      if (area.querySelector('.themeasy-library-add-button')) {
        return;
      }

      const button = buildAddSectionButton(doc);
      const dragTitle = area.querySelector('.elementor-add-section-drag-title');

      if (dragTitle) {
        area.insertBefore(button, dragTitle);
      } else {
        area.appendChild(button);
      }

      nativeInjected = true;
      // A native launcher now exists — cancel any pending fallback and retire
      // the floating button if a slow render had already raised it.
      window.clearTimeout(fallbackTimer);
      removeFloatingLauncher();
    });
  }

  /**
   * Build a Themeasy launcher styled like Elementor's add-section buttons. The
   * node is created in the iframe's own document so it belongs to that context.
   *
   * @param {Document} doc - The preview iframe document.
   * @returns {HTMLElement}
   */
  function buildAddSectionButton(doc) {
    const button = doc.createElement('button');
    button.type = 'button';
    button.className = 'elementor-add-section-area-button themeasy-library-add-button';
    button.setAttribute('data-tooltip', i18n.launch || 'Themeasy Library');
    button.setAttribute('aria-label', i18n.launch || 'Themeasy Library');
    button.setAttribute('title', i18n.launch || 'Themeasy Library');

    const icon = doc.createElement('span');
    icon.style.cssText = 'display:block;width:20px;height:20px;background-color:currentColor;' +
      '-webkit-mask:url("' + THEMEASY_MARK + '") center/contain no-repeat;' +
      'mask:url("' + THEMEASY_MARK + '") center/contain no-repeat;';
    button.appendChild(icon);

    button.addEventListener('click', function (event) {
      event.preventDefault();
      event.stopPropagation();
      open();
    });

    return button;
  }

  // ------------------------------------------------------------------------
  // Modal shell
  // ------------------------------------------------------------------------

  /**
   * Build the modal DOM once and cache references.
   *
   * @returns {void}
   */
  function buildModal() {
    if (state.built) {
      return;
    }

    // Header.
    dom.search = el('input', {
      type: 'search',
      placeholder: i18n.searchPlaceholder || '',
      'aria-label': i18n.searchPlaceholder || ''
    });
    dom.search.addEventListener('input', debounce(function () {
      state.filters.search = dom.search.value.trim();
      state.page = 1;
      loadTemplates();
    }, 350));

    const closeBtn = el('button', {
      type: 'button',
      class: 'themeasy-library__close',
      'aria-label': i18n.close || 'Close',
      text: '×'
    });
    closeBtn.addEventListener('click', close);

    const header = el('div', { class: 'themeasy-library__header' }, [
      el('div', { class: 'themeasy-library__brand' }, [
        el('h2', { class: 'themeasy-library__title', text: i18n.title || 'Themeasy Library' }),
      ]),
      el('div', { class: 'themeasy-library__search' }, [dom.search]),
      closeBtn
    ]);

    // Group tab bar (Pages / Blocks) — populated by renderGroups() once the
    // categories arrive; stays hidden for a flat (no-hierarchy) catalog.
    dom.groups = el('div', { class: 'themeasy-library__groups themeasy-library__hidden' });

    // Body: sidebar + main.
    dom.sidebar = el('div', { class: 'themeasy-library__sidebar' });
    dom.tags = el('div', { class: 'themeasy-library__tags' });
    dom.grid = el('div', { class: 'themeasy-library__grid' });
    dom.state = el('div', {
      class: 'themeasy-library__state themeasy-library__hidden',
      role: 'status',
      'aria-live': 'polite'
    });
    dom.scroll = el('div', { class: 'themeasy-library__scroll' }, [dom.grid, dom.state]);

    dom.count = el('span', { class: 'themeasy-library__count' });
    dom.prev = el('button', { type: 'button', class: 'themeasy-library__page-btn', text: i18n.prev || 'Previous' });
    dom.next = el('button', { type: 'button', class: 'themeasy-library__page-btn', text: i18n.next || 'Next' });
    dom.pageInfo = el('span', { class: 'themeasy-library__page-info' });
    dom.prev.addEventListener('click', function () { goToPage(state.page - 1); });
    dom.next.addEventListener('click', function () { goToPage(state.page + 1); });

    const footer = el('div', { class: 'themeasy-library__footer' }, [
      dom.count,
      el('div', { class: 'themeasy-library__pagination' }, [dom.prev, dom.pageInfo, dom.next])
    ]);

    const main = el('div', { class: 'themeasy-library__main' }, [dom.tags, dom.scroll, footer]);
    const body = el('div', { class: 'themeasy-library__body' }, [dom.sidebar, main]);

    dom.modal = el('div', {
      class: 'themeasy-library-modal',
      role: 'dialog',
      'aria-modal': 'true',
      'aria-label': i18n.title || 'Themeasy Library'
    }, [header, dom.groups, body]);

    dom.overlay = el('div', { class: 'themeasy-library-overlay' }, [dom.modal]);

    // Close on backdrop click (outside the modal only).
    dom.overlay.addEventListener('click', function (event) {
      if (event.target === dom.overlay) {
        close();
      }
    });

    document.body.appendChild(dom.overlay);
    state.built = true;
  }

  // ------------------------------------------------------------------------
  // Open / close
  // ------------------------------------------------------------------------

  /**
   * Open the modal, building + loading on first use.
   *
   * @returns {void}
   */
  function open() {
    buildModal();
    // Force reflow so the opening transition runs on first paint.
    void dom.overlay.offsetWidth;
    dom.overlay.classList.add('is-open');
    document.addEventListener('keydown', onKeydown);

    if (dom.search) {
      dom.search.focus();
    }

    loadMeta();
    loadTemplates();
  }

  /**
   * Close the modal.
   *
   * @returns {void}
   */
  function close() {
    if (dom.overlay) {
      dom.overlay.classList.remove('is-open');
    }
    document.removeEventListener('keydown', onKeydown);
  }

  /**
   * Close on Escape.
   *
   * @param {KeyboardEvent} event
   * @returns {void}
   */
  function onKeydown(event) {
    if (event.key === 'Escape') {
      close();
    }
  }

  // ------------------------------------------------------------------------
  // Data loading
  // ------------------------------------------------------------------------

  /**
   * Load the category + tag taxonomies. Each resource latches independently on
   * success only, so a failed fetch is re-attempted on the next open()/Retry
   * instead of leaving a permanently empty sidebar or tag bar.
   *
   * @returns {void}
   */
  function loadMeta() {
    loadCategories();
    loadTags();
  }

  /**
   * Load the category sidebar data (self-guarded, retries after failure).
   *
   * Groups (tabs) are derived here too: when they land for the first time the
   * default tab becomes the effective category filter, which needs one reload —
   * the sequence guard lets it win over the still-in-flight unfiltered load.
   *
   * @returns {void}
   */
  function loadCategories() {
    if (state.metaCategories !== 'idle') {
      return;
    }
    state.metaCategories = 'loading';

    browse('categories').then(function (data) {
      state.metaCategories = 'done';
      state.categories = Array.isArray(data) ? data : [];
      state.groups = deriveGroups(state.categories);
      const filterChanged = applyDefaultGroup();
      renderGroups();
      renderCategories();
      renderTags();
      if (filterChanged) {
        loadTemplates();
      } else {
        refreshCardTags();
      }
    }).catch(function () {
      state.metaCategories = 'idle';
      state.categories = [];
      state.groups = [];
      state.activeGroup = '';
      renderGroups();
      renderCategories();
      renderTags();
    });
  }

  /**
   * Load the tag filter bar data (self-guarded, retries after failure).
   *
   * @returns {void}
   */
  function loadTags() {
    if (state.metaTags !== 'idle') {
      return;
    }
    state.metaTags = 'loading';

    browse('tags').then(function (data) {
      state.metaTags = 'done';
      state.tags = Array.isArray(data) ? data : [];
      renderTags();
      refreshCardTags();
    }).catch(function () {
      state.metaTags = 'idle';
      state.tags = [];
      renderTags();
    });
  }

  /**
   * Load the templates listing for the current filters + page. Responses are
   * sequence-guarded: only the newest request may touch the state, so rapid
   * filter changes cannot race an older, slower response into the grid.
   *
   * @returns {void}
   */
  function loadTemplates() {
    const seq = ++state.requestSeq;
    showState(i18n.loading || 'Loading...', true);

    const query = {
      page: state.page,
      per_page: cfg.perPage || 24
    };
    if (state.filters.category) { query.category = state.filters.category; }
    if (state.filters.tag) { query.tag = state.filters.tag; }
    if (state.filters.search) { query.search = state.filters.search; }

    browse('templates', query).then(function (data) {
      if (seq !== state.requestSeq) {
        return;
      }
      state.templates = (data && Array.isArray(data.items)) ? data.items : [];
      state.total = (data && data.total) ? parseInt(data.total, 10) : 0;
      state.pages = (data && data.pages) ? parseInt(data.pages, 10) : 1;
      state.page = (data && data.page) ? parseInt(data.page, 10) : state.page;
      renderGrid();
      renderPagination();
    }).catch(function (error) {
      if (seq !== state.requestSeq) {
        return;
      }
      showError(error && error.message ? error.message : (i18n.error || 'Error'));
    });
  }

  // ------------------------------------------------------------------------
  // Rendering
  // ------------------------------------------------------------------------

  /**
   * Derive the group tabs from the category list: a group is a root term that
   * at least one other term names as its parent. A catalog without hierarchy
   * yields no groups and the panel keeps its original tab-less layout.
   *
   * @param {Array} categories
   * @returns {Array}
   */
  function deriveGroups(categories) {
    const referenced = {};
    categories.forEach(function (cat) {
      if (cat && cat.parent) {
        referenced[cat.parent] = true;
      }
    });

    const groups = categories.filter(function (cat) {
      return !!(cat && cat.slug && !cat.parent && referenced[cat.slug] === true);
    });

    // The default (full-page) group leads the tab bar when present; the stable
    // sort keeps the API order for everything else.
    groups.sort(function (a, b) {
      return (b.slug === DEFAULT_GROUP ? 1 : 0) - (a.slug === DEFAULT_GROUP ? 1 : 0);
    });

    return groups;
  }

  /**
   * Find a group tab by slug.
   *
   * @param {string} slug
   * @returns {Object|null}
   */
  function findGroup(slug) {
    for (let i = 0; i < state.groups.length; i++) {
      if (state.groups[i].slug === slug) {
        return state.groups[i];
      }
    }
    return null;
  }

  /**
   * Ensure a valid active tab once groups are known: keep a still-valid
   * selection (reopening the modal preserves the tab), otherwise activate the
   * default group and point the category filter at its slug.
   *
   * @returns {boolean} True when the effective filter changed (needs a reload).
   */
  function applyDefaultGroup() {
    if (!state.groups.length) {
      state.activeGroup = '';
      return false;
    }

    if (state.activeGroup && findGroup(state.activeGroup)) {
      return false;
    }

    const initial = findGroup(DEFAULT_GROUP) ? DEFAULT_GROUP : state.groups[0].slug;
    state.activeGroup = initial;
    state.filters.category = initial;
    state.page = 1;
    return true;
  }

  /**
   * A term's template count as a number.
   *
   * @param {Object} term
   * @returns {number}
   */
  function countOf(term) {
    return parseInt(term && term.count, 10) || 0;
  }

  /**
   * Templates in a group. The backstage files a template under its whole
   * category path (Blocks > Hero), so the group's own count already holds its
   * children's; a group whose templates sit only in the children (the theme's
   * local library) counts 0 of its own. The group is the larger of the two,
   * never their sum, which counted every template twice.
   *
   * @param {Object} group
   * @returns {number}
   */
  function groupTotal(group) {
    let children = 0;

    state.categories.forEach(function (cat) {
      if (cat && cat.parent === group.slug) {
        children += countOf(cat);
      }
    });

    return Math.max(countOf(group), children);
  }

  /**
   * Templates in the whole catalog: every group plus the root categories
   * outside one. 0 until the categories are loaded.
   *
   * @returns {number}
   */
  function catalogTotal() {
    let total = 0;

    state.categories.forEach(function (cat) {
      if (cat && cat.slug && !cat.parent) {
        total += findGroup(cat.slug) ? groupTotal(cat) : countOf(cat);
      }
    });

    return total;
  }

  /**
   * Tag slugs that only restate a category or a group: "hero", "cards", and
   * "page" for the "pages" group (singular and plural both count). They say
   * what a template is, which the tabs and the sidebar already filter by.
   *
   * @returns {Object<string,boolean>}
   */
  function categoryTagSlugs() {
    const slugs = Object.create(null);

    state.categories.forEach(function (cat) {
      if (cat && cat.slug) {
        slugs[cat.slug] = true;
        slugs[cat.slug.replace(/s$/, '')] = true;
        slugs[cat.slug + 's'] = true;
      }
    });

    return slugs;
  }

  /**
   * The tags the bar shows: the most-used ones that still narrow the list. A
   * tag that restates a category is left out, and so is one every template
   * carries (it filters nothing). The active tag always stays in the bar, so a
   * filter can never be on without a pill to turn it off.
   *
   * @returns {Array}
   */
  function topTags() {
    const skip = categoryTagSlugs();
    const total = catalogTotal();

    const tags = state.tags.filter(function (tag) {
      return !!(tag && tag.slug) && skip[tag.slug] !== true && (total < 1 || countOf(tag) < total);
    }).sort(function (a, b) {
      return countOf(b) - countOf(a) || String(a.name || a.slug).localeCompare(String(b.name || b.slug));
    }).slice(0, TAG_BAR_SIZE);

    const active = state.filters.tag;
    const shown = tags.some(function (tag) {
      return tag.slug === active;
    });

    if (active && !shown) {
      state.tags.forEach(function (tag) {
        if (tag && tag.slug === active) {
          tags.push(tag);
        }
      });
    }

    return tags;
  }

  /**
   * Build the picker of the few tags a card shows: the ones the whole library
   * uses most (tone, style, industry), never one that restates a category. A
   * template's tags arrive sorted by name, so the first ones were noise
   * ("3d", "Archivo").
   *
   * @returns {function(Object): Array}
   */
  function cardTagPicker() {
    const skip = categoryTagSlugs();
    const uses = Object.create(null);

    state.tags.forEach(function (tag) {
      if (tag && tag.slug) {
        uses[tag.slug] = countOf(tag);
      }
    });

    return function (tpl) {
      return (Array.isArray(tpl.tags) ? tpl.tags : []).filter(function (tag) {
        return !!(tag && tag.name) && skip[tag.slug] !== true;
      }).sort(function (a, b) {
        return (uses[b.slug] || 0) - (uses[a.slug] || 0) || String(a.name).localeCompare(String(b.name));
      }).slice(0, CARD_TAGS_SIZE);
    };
  }

  /**
   * Render the group tab bar (hidden when the catalog has no hierarchy).
   *
   * @returns {void}
   */
  function renderGroups() {
    dom.groups.textContent = '';

    if (!state.groups.length) {
      dom.groups.classList.add('themeasy-library__hidden');
      return;
    }

    dom.groups.classList.remove('themeasy-library__hidden');
    state.groups.forEach(function (group) {
      dom.groups.appendChild(buildGroupTab(group));
    });
  }

  /**
   * Build one group tab. Activating it scopes the whole browse to that group:
   * the category filter becomes the group slug ("All {Group}") and the sidebar
   * re-renders with the group's children.
   *
   * @param {Object} group
   * @returns {HTMLElement}
   */
  function buildGroupTab(group) {
    const tab = el('button', {
      type: 'button',
      class: 'themeasy-library__group' + (state.activeGroup === group.slug ? ' is-active' : ''),
      text: group.name || group.slug
    });

    tab.addEventListener('click', function () {
      if (state.activeGroup === group.slug) {
        return;
      }
      state.activeGroup = group.slug;
      state.filters.category = group.slug;
      state.page = 1;
      renderGroups();
      renderCategories();
      loadTemplates();
    });

    return tab;
  }

  /**
   * Render the category sidebar.
   *
   * Without groups this is the original single-level list. With groups the
   * sidebar scopes to the active tab: "All {Group}" (the group slug itself —
   * the backstage expands children server-side, Library_Local matches the
   * group dir) followed by the group's child categories. Root categories
   * outside any group stay reachable from every tab; deeper descendants are
   * not listed (the group filter still includes them server-side).
   *
   * @returns {void}
   */
  function renderCategories() {
    dom.sidebar.textContent = '';

    if (!state.groups.length) {
      dom.sidebar.appendChild(buildCategoryButton('', i18n.allCategories || 'All', null));

      state.categories.forEach(function (cat) {
        if (cat && cat.slug) {
          dom.sidebar.appendChild(buildCategoryButton(cat.slug, cat.name || cat.slug, cat.count));
        }
      });
      return;
    }

    const group = findGroup(state.activeGroup);
    const children = [];
    const loose = [];

    state.categories.forEach(function (cat) {
      if (!cat || !cat.slug) {
        return;
      }
      if (cat.parent === state.activeGroup) {
        children.push(cat);
      } else if (!cat.parent && !findGroup(cat.slug)) {
        loose.push(cat);
      }
    });

    const groupName = group ? (group.name || group.slug) : '';
    dom.sidebar.appendChild(buildCategoryButton(
      state.activeGroup,
      format(i18n.allIn || 'All %1$s', [groupName]),
      group ? groupTotal(group) : 0
    ));

    children.concat(loose).forEach(function (cat) {
      dom.sidebar.appendChild(buildCategoryButton(cat.slug, cat.name || cat.slug, cat.count));
    });
  }

  /**
   * Build one category button.
   *
   * @param {string} slug
   * @param {string} name
   * @param {number|null} count
   * @returns {HTMLElement}
   */
  function buildCategoryButton(slug, name, count) {
    const children = [el('span', { text: name })];
    if (count !== null && count !== undefined) {
      children.push(el('span', { class: 'themeasy-library__cat-count', text: String(count) }));
    }

    const button = el('button', {
      type: 'button',
      class: 'themeasy-library__cat' + (state.filters.category === slug ? ' is-active' : '')
    }, children);

    button.addEventListener('click', function () {
      if (state.filters.category === slug) {
        return;
      }
      state.filters.category = slug;
      state.page = 1;
      renderCategories();
      loadTemplates();
    });

    return button;
  }

  /**
   * Render the tag filter bar: "All tags" plus the topTags() pills. The bar
   * waits for the categories, because topTags() leaves out the tags that
   * restate one: drawn before them, the pills would reshuffle a moment later.
   *
   * @returns {void}
   */
  function renderTags() {
    dom.tags.textContent = '';

    const tags = (state.metaCategories === 'loading') ? [] : topTags();

    if (!tags.length) {
      dom.tags.classList.add('themeasy-library__hidden');
      return;
    }
    dom.tags.classList.remove('themeasy-library__hidden');

    dom.tags.appendChild(buildTagChip('', i18n.allTags || 'All tags'));
    tags.forEach(function (tag) {
      dom.tags.appendChild(buildTagChip(tag.slug, tag.name || tag.slug));
    });
  }

  /**
   * Build one tag chip (toggles the active tag).
   *
   * @param {string} slug
   * @param {string} name
   * @returns {HTMLElement}
   */
  function buildTagChip(slug, name) {
    const chip = el('button', {
      type: 'button',
      class: 'themeasy-library__tag' + (state.filters.tag === slug ? ' is-active' : ''),
      text: name
    });

    chip.addEventListener('click', function () {
      const next = (state.filters.tag === slug) ? '' : slug;
      state.filters.tag = next;
      state.page = 1;
      renderTags();
      loadTemplates();
    });

    return chip;
  }

  /**
   * Render the card grid for the current templates.
   *
   * @returns {void}
   */
  function renderGrid() {
    if (!state.templates.length) {
      showState(i18n.empty || 'No templates.', false);
      return;
    }

    hideState();
    dom.grid.textContent = '';
    const pickTags = cardTagPicker();
    state.templates.forEach(function (tpl) {
      dom.grid.appendChild(buildCard(tpl, pickTags));
    });
  }

  /**
   * Redraw the grid when the tag or category list lands after it, so the card
   * tags are picked with the library-wide counts. Left alone while a state
   * block (loading, empty, error) is up: the load in flight draws the grid.
   *
   * @returns {void}
   */
  function refreshCardTags() {
    if (state.templates.length && !dom.grid.classList.contains('themeasy-library__hidden')) {
      renderGrid();
    }
  }

  /**
   * Build one template card.
   *
   * @param {Object} tpl
   * @param {function(Object): Array} pickTags - The grid's cardTagPicker().
   * @returns {HTMLElement}
   */
  function buildCard(tpl, pickTags) {
    const isTheme = tpl.source === 'theme';
    const isPro = tpl.tier === 'pro';
    let isLocked = isPro;

    // Cover (image or branded fallback).
    let cover;
    if (isHttpUrl(tpl.cover)) {
      cover = el('img', { src: tpl.cover, alt: '', loading: 'lazy' });
    } else {
      cover = el('div', { class: 'themeasy-library__cover-fallback' });
    }

    // Tier badge — theme-bundled templates carry their own mark so they read
    // as "ships with your theme" next to the cloud Free/Pro items.
    let badgeClass = 'themeasy-library__badge';
    let badgeText = i18n.freeBadge || 'Free';
    if (isTheme) {
      badgeClass += ' themeasy-library__badge--theme';
      badgeText = i18n.themeBadge || 'Theme';
    } else if (isPro) {
      badgeClass += ' themeasy-library__badge--pro';
      badgeText = i18n.proBadge || 'Pro';
    }

    const coverChildren = [cover];
    coverChildren.push(el('span', { class: badgeClass, text: badgeText }));

    if (isLocked) {
      coverChildren.push(buildLockOverlay());
    }

    const coverWrap = el('div', { class: 'themeasy-library__cover' }, coverChildren);

    // Tags row.
    const tagNodes = pickTags(tpl).map(function (tag) {
      return el('span', { class: 'themeasy-library__card-tag', text: tag.name });
    });

    const body = el('div', { class: 'themeasy-library__card-body' }, [
      el('h3', { class: 'themeasy-library__card-title', text: tpl.title || '' }),
      tagNodes.length ? el('div', { class: 'themeasy-library__card-tags' }, tagNodes) : null,
      buildCardActions(tpl, isLocked)
    ]);

    return el('div', {
      class: 'themeasy-library__card' + (isLocked ? ' themeasy-library__card--locked' : '')
    }, [coverWrap, body]);
  }

  /**
   * Build the lock overlay of a locked Pro template. Shown on
   * hover, so it carries the full "Upgrade to insert" wording — the action-row
   * button below stays short.
   *
   * @returns {HTMLElement}
   */
  function buildLockOverlay() {
    const children = [el('span', { class: 'themeasy-library__lock-icon' })];

    if (isHttpUrl(cfg.upgradeUrl)) {
      children.push(el('a', {
        class: 'themeasy-library__lock-cta',
        href: cfg.upgradeUrl,
        target: '_blank',
        rel: 'noopener',
        text: i18n.upgradeToInsert || i18n.upgrade || 'Upgrade'
      }));
    } else {
      children.push(el('span', { class: 'themeasy-library__lock-cta', text: i18n.locked || 'Pro' }));
    }

    return el('div', { class: 'themeasy-library__lock' }, children);
  }

  /**
   * Public catalog page for a template (library.themeasy.co), built from the
   * category + slug: /templates/{category}/{slug}/, falling back to the flat
   * /template/{slug}/ route for a category-less template. The cms backstage
   * preview_url is never used as a card link — it is a private, chrome-less
   * render meant for the catalog's iframe, not a human-facing destination.
   *
   * @param {Object} tpl
   * @returns {string} Empty when no catalog URL can be built.
   */
  function catalogTemplateUrl(tpl) {
    if (!isHttpUrl(cfg.catalogUrl) || typeof tpl.slug !== 'string' || !tpl.slug) {
      return '';
    }

    const base = String(cfg.catalogUrl).replace(/\/+$/, '');
    const category = (tpl.category && typeof tpl.category.slug === 'string') ? tpl.category.slug : '';

    // Plural "/templates/{cat}/{slug}/" vs singular "/template/{slug}/" is
    // intentional — it mirrors the catalog's routing, not a typo.
    if (category) {
      return base + '/templates/' + encodeURIComponent(category) + '/' + encodeURIComponent(tpl.slug) + '/';
    }
    return base + '/template/' + encodeURIComponent(tpl.slug) + '/';
  }

  /**
   * Build the card action row: a public Preview link (cloud templates only)
   * plus either Insert or, on a locked card, an Upgrade CTA.
   *
   * @param {Object} tpl
   * @param {boolean} isLocked
   * @returns {HTMLElement}
   */
  function buildCardActions(tpl, isLocked) {
    const actions = [];

    // Theme-bundled templates have no public catalog page — no Preview link.
    const previewUrl = (tpl.source === 'theme') ? '' : catalogTemplateUrl(tpl);

    if (previewUrl) {
      actions.push(el('a', {
        class: 'themeasy-library__btn',
        href: previewUrl,
        target: '_blank',
        rel: 'noopener',
        text: i18n.preview || 'Preview'
      }));
    }

    if (isLocked) {
      // Locked: the action is a link to the upgrade page, not an insert. Short
      // label — the full wording lives on the hover overlay and this title
      // tooltip.
      if (isHttpUrl(cfg.upgradeUrl)) {
        actions.push(el('a', {
          class: 'themeasy-library__btn themeasy-library__btn--primary',
          href: cfg.upgradeUrl,
          target: '_blank',
          rel: 'noopener',
          title: i18n.upgradeToInsert || '',
          text: i18n.upgrade || 'Upgrade'
        }));
      }
    } else {
      const insertBtn = el('button', {
        type: 'button',
        class: 'themeasy-library__btn themeasy-library__btn--primary',
        text: i18n.insert || 'Insert'
      });
      insertBtn.addEventListener('click', function () {
        insertTemplate(tpl, insertBtn);
      });
      actions.push(insertBtn);
    }

    return el('div', { class: 'themeasy-library__card-actions' }, actions);
  }

  // ------------------------------------------------------------------------
  // Insertion
  // ------------------------------------------------------------------------

  /**
   * Fetch a template's payload and insert its elements into the open document.
   * Cloud templates come through the same-origin proxy; theme-bundled
   * templates are read from the theme's local JSON (source+key).
   *
   * @param {Object} tpl
   * @param {HTMLElement} button
   * @returns {void}
   */
  function insertTemplate(tpl, button) {
    if (button.disabled) {
      return;
    }

    const original = button.textContent;
    button.disabled = true;
    button.textContent = i18n.inserting || 'Inserting...';

    const fields = { action: 'themeasy_library_insert' };
    if (tpl.source === 'theme') {
      fields.source = 'theme';
      fields.key = String(tpl.key || '');
    } else {
      fields.id = parseInt(tpl.id, 10) || 0;
    }

    postForm(fields).then(function (data) {
      const result = importIntoDocument(data);
      if (!result) {
        throw new Error(i18n.error || 'Error');
      }
      const message = result.leftOut ? leftOutMessage(result.leftOut) : (i18n.inserted || 'Template inserted.');
      notify(isBoxedPageTemplate() && i18n.fullWidthHint ? message + ' ' + i18n.fullWidthHint : message, false);
      close();
    }).catch(function (error) {
      button.disabled = false;
      button.textContent = original;
      notify(error && error.message ? error.message : (i18n.error || 'Error'), true);
    });
  }

  /**
   * Insert an export envelope's top-level elements into the current document via
   * the Elementor command API. Page settings are intentionally left untouched —
   * this inserts content, it does not replace the page.
   *
   * The widgets this editor does not register are left out first, see
   * stripUnknownWidgets().
   *
   * @param {Object} envelope - { content: [ ...Elementor elements... ] }
   * @returns {{leftOut: number}|false} False when the editor API is unavailable or there is nothing to insert.
   */
  function importIntoDocument(envelope) {
    const dropped = { count: 0 };
    const content = (envelope && Array.isArray(envelope.content)) ? stripUnknownWidgets(envelope.content, dropped) : null;

    if (!content || !content.length) {
      return false;
    }

    if (typeof window.$e === 'undefined' || !window.$e.run ||
        typeof window.elementor === 'undefined' || !window.elementor.getPreviewContainer) {
      return false;
    }

    const root = window.elementor.getPreviewContainer();
    if (!root) {
      return false;
    }

    try {
      // Append sequentially with an explicit, manually advanced index so the
      // imported order is preserved regardless of container update timing.
      let at = childCount(root);
      content.forEach(function (model) {
        window.$e.run('document/elements/create', {
          container: root,
          model: regenerateIds(model),
          options: { at: at }
        });
        at++;
      });
      return { leftOut: dropped.count };
    } catch (error) {
      return false;
    }
  }

  /**
   * Drop the widgets this editor does not register from a template tree,
   * keeping the rest of each container (backlog #291). Elementor rejects an
   * unknown widget type with ElementTypeNotFound and discards the whole
   * top-level element that holds it, so a template built with widgets this
   * site does not have used to lose entire sections without a word.
   *
   * @param {Array} models - Elementor elements; their `elements` are filtered in place.
   * @param {{count: number}} dropped - Incremented once per widget left out.
   * @returns {Array}
   */
  function stripUnknownWidgets(models, dropped) {
    return models.filter(function (node) {
      if (!node || typeof node !== 'object') {
        return false;
      }
      if (node.elType === 'widget' && !isRegisteredWidget(node.widgetType)) {
        dropped.count++;
        return false;
      }
      if (Array.isArray(node.elements)) {
        node.elements = stripUnknownWidgets(node.elements, dropped);
      }
      return true;
    });
  }

  /**
   * Whether the editor registers a widget type. Without the registry there is
   * nothing to compare against, so the widget is kept and Elementor decides.
   *
   * @param {string} type
   * @returns {boolean}
   */
  function isRegisteredWidget(type) {
    const registry = window.elementor && window.elementor.widgetsCache;
    if (!registry) {
      return true;
    }
    return typeof type === 'string' && Object.prototype.hasOwnProperty.call(registry, type);
  }

  /**
   * The insert notice when widgets were left out: how many, and why.
   *
   * @param {number} count
   * @returns {string}
   */
  function leftOutMessage(count) {
    const sentence = count === 1
      ? (i18n.leftOutOne || 'Template inserted, but 1 element was left out.')
      : format(i18n.leftOutMany || 'Template inserted, but %1$s elements were left out.', [count]);
    return i18n.leftOutReason ? sentence + ' ' + i18n.leftOutReason : sentence;
  }

  /**
   * Whether a full-page template just landed in a column the host theme boxes
   * (backlog #292): a template of the full-page group, on a theme that is not a
   * Themeasy theme, with the Page Layout still on a theme template, and the
   * document narrower than the preview (Twenty Twenty-Five boxes it at 645px;
   * Hello Elementor does not). The insert only warns: it never changes the
   * page settings.
   *
   * @returns {boolean}
   */
  function isBoxedPageTemplate() {
    if (state.activeGroup !== DEFAULT_GROUP || cfg.themeasyTheme) {
      return false;
    }

    const doc = window.elementor && window.elementor.documents && window.elementor.documents.getCurrent
      ? window.elementor.documents.getCurrent()
      : null;
    const frame = document.getElementById('elementor-preview-iframe');
    const previewDoc = frame ? frame.contentDocument : null;

    if (!doc || !previewDoc) {
      return false;
    }

    const layout = doc.container && doc.container.settings ? doc.container.settings.get('template') : '';
    if (layout === 'elementor_header_footer' || layout === 'elementor_canvas') {
      return false;
    }

    const wrapper = previewDoc.querySelector('[data-elementor-id="' + doc.id + '"]');
    return !!wrapper && wrapper.getBoundingClientRect().width < previewDoc.documentElement.clientWidth - 1;
  }

  /**
   * Best-effort count of a container's current top-level children.
   *
   * @param {Object} container
   * @returns {number}
   */
  function childCount(container) {
    if (container.children && typeof container.children.length === 'number') {
      return container.children.length;
    }
    if (container.view && container.view.collection && typeof container.view.collection.length === 'number') {
      return container.view.collection.length;
    }
    return 0;
  }

  /**
   * Deep-clone an element model and assign fresh ids to every node, so inserting
   * the same template twice never collides ids (Elementor's own import does the
   * same). The source model comes from JSON, so a JSON round-trip clones it safely.
   *
   * @param {Object} model
   * @returns {Object}
   */
  function regenerateIds(model) {
    let clone;
    try {
      clone = JSON.parse(JSON.stringify(model));
    } catch (error) {
      return model;
    }

    (function walk(node) {
      if (!node || typeof node !== 'object') {
        return;
      }
      if (node.id) {
        node.id = newElementId();
      }
      if (Array.isArray(node.elements)) {
        node.elements.forEach(walk);
      }
    })(clone);

    return clone;
  }

  /**
   * A fresh Elementor element id (7-char), preferring the editor's own helper.
   *
   * @returns {string}
   */
  function newElementId() {
    if (window.elementorCommon && window.elementorCommon.helpers && window.elementorCommon.helpers.getUniqueId) {
      return window.elementorCommon.helpers.getUniqueId();
    }
    return Math.random().toString(36).slice(2, 9);
  }

  /**
   * Surface a message through Elementor's toast, falling back to alert on error.
   *
   * @param {string} message
   * @param {boolean} isError
   * @returns {void}
   */
  function notify(message, isError) {
    if (window.elementor && window.elementor.notifications && window.elementor.notifications.showToast) {
      window.elementor.notifications.showToast({ message: message });
      return;
    }
    if (isError) {
      window.alert(message);
    }
  }

  /**
   * Render pagination controls + the result count.
   *
   * @returns {void}
   */
  function renderPagination() {
    dom.count.textContent = state.total + ' ' + (i18n.results || '');
    dom.pageInfo.textContent = format(i18n.pageOf || 'Page %1$s of %2$s', [state.page, state.pages]);
    dom.prev.disabled = state.page <= 1;
    dom.next.disabled = state.page >= state.pages;
  }

  /**
   * Navigate to a page (clamped) and reload. Concurrent loads are safe — the
   * request sequence guard in loadTemplates() lets the newest one win.
   *
   * @param {number} page
   * @returns {void}
   */
  function goToPage(page) {
    const target = Math.max(1, Math.min(state.pages, page));
    if (target === state.page) {
      return;
    }
    state.page = target;
    loadTemplates();
    dom.scroll.scrollTop = 0;
  }

  // ------------------------------------------------------------------------
  // States (loading / empty / error)
  // ------------------------------------------------------------------------

  /**
   * Show a centered state block (loading or empty).
   *
   * @param {string} message
   * @param {boolean} spinner
   * @returns {void}
   */
  function showState(message, spinner) {
    dom.grid.classList.add('themeasy-library__hidden');
    dom.state.classList.remove('themeasy-library__hidden');
    dom.state.textContent = '';

    if (spinner) {
      dom.state.appendChild(el('div', { class: 'themeasy-library__spinner' }));
    }
    dom.state.appendChild(el('p', { text: message }));
  }

  /**
   * Show the error state with a retry button. Retry re-attempts everything the
   * modal needs — the listing AND any meta resource that failed earlier (the
   * meta loaders self-guard, so already-loaded resources are not re-fetched).
   *
   * @param {string} message
   * @returns {void}
   */
  function showError(message) {
    showState(message, false);
    const retry = el('button', { type: 'button', class: 'themeasy-library__btn themeasy-library__btn--primary', text: i18n.retry || 'Retry' });
    retry.addEventListener('click', function () {
      loadMeta();
      loadTemplates();
    });
    dom.state.appendChild(retry);
  }

  /**
   * Hide the state block and reveal the grid.
   *
   * @returns {void}
   */
  function hideState() {
    dom.state.classList.add('themeasy-library__hidden');
    dom.grid.classList.remove('themeasy-library__hidden');
  }

  // ------------------------------------------------------------------------
  // Boot
  // ------------------------------------------------------------------------

  /**
   * Expose a tiny public surface (open/close) and mount the launcher.
   */
  window.Themeasy.library = {
    open: open,
    close: close
  };

  function boot() {
    // Prefer the native add-section buttons (inside the preview iframe); the
    // floating launcher is the fallback when the Elementor API is unavailable.
    mountAddSectionLaunchers();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot, { once: true });
  } else {
    boot();
  }
})(window, document);
